﻿@page "/"

@inject NavigationManager Navigation

<PageTitle>ShipmentTracker - Home</PageTitle>

<h1>Welcome to ShipmentTracker</h1>
<p>Your trusted partner in logistics and shipment management.</p>

<hr />

<h3>Track Your Shipment</h3>
<p>Enter your tracking number below to get real-time status updates.</p>

<div class="d-flex gap-2" style="max-width: 500px;">
    <input type="text" class="form-control" placeholder="e.g. TRK-2026-001"
           @bind="trackingNumber" @bind:event="oninput"
           @onkeydown="HandleKeyDown" />
    <button class="btn btn-primary" disabled="@string.IsNullOrWhiteSpace(trackingNumber)"
            @onclick="TrackShipment">Track</button>
</div>

@code {
    private string? trackingNumber;

    private void TrackShipment()
    {
        if (!string.IsNullOrWhiteSpace(trackingNumber))
        {
            Navigation.NavigateTo($"/track/{Uri.EscapeDataString(trackingNumber.Trim())}");
        }
    }

    private void HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            TrackShipment();
        }
    }
}

