@page "/track/{TrackingNumber?}"

@inject IShipmentService ShipmentService
@inject NavigationManager Navigation

<PageTitle>Track Shipment</PageTitle>

<h2>Track Shipment</h2>

@if (string.IsNullOrWhiteSpace(TrackingNumber))
{
    <p>Enter a tracking number to look up your shipment.</p>
    <div class="d-flex gap-2" style="max-width: 500px;">
        <input type="text" class="form-control" placeholder="e.g. TRK-2026-001"
               @bind="searchInput" @bind:event="oninput"
               @onkeydown="HandleKeyDown" />
        <button class="btn btn-primary" disabled="@string.IsNullOrWhiteSpace(searchInput)"
                @onclick="Search">Search</button>
    </div>
}
else if (loading)
{
    <p><em>Loading shipment details...</em></p>
}
else if (shipment is null)
{
    <div class="alert alert-warning">Shipment not found for tracking number: <strong>@TrackingNumber</strong></div>
    <button class="btn btn-secondary" @onclick="@(() => Navigation.NavigateTo("/track"))">Try Another</button>
}
else
{
    <div class="card" style="max-width: 600px;">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>@shipment.TrackingNumber</strong>
            <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
        </div>
        <div class="card-body">
            <dl class="row mb-0">
                <dt class="col-sm-5">Recipient</dt>
                <dd class="col-sm-7">@shipment.RecipientName</dd>

                <dt class="col-sm-5">Origin</dt>
                <dd class="col-sm-7">@shipment.Origin</dd>

                <dt class="col-sm-5">Destination</dt>
                <dd class="col-sm-7">@shipment.Destination</dd>

                <dt class="col-sm-5">Shipped Date</dt>
                <dd class="col-sm-7">@shipment.ShippedDate.ToString("MMM dd, yyyy")</dd>

                <dt class="col-sm-5">Estimated Delivery</dt>
                <dd class="col-sm-7">@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</dd>

                @if (!string.IsNullOrWhiteSpace(shipment.Notes))
                {
                    <dt class="col-sm-5">Notes</dt>
                    <dd class="col-sm-7">@shipment.Notes</dd>
                }
            </dl>
        </div>
    </div>
}

@code {
    [Parameter]
    public string? TrackingNumber { get; set; }

    private ShipmentDto? shipment;
    private bool loading;
    private string? searchInput;

    protected override async Task OnParametersSetAsync()
    {
        if (!string.IsNullOrWhiteSpace(TrackingNumber))
        {
            loading = true;
            shipment = await ShipmentService.GetByTrackingNumberAsync(TrackingNumber);
            loading = false;
        }
    }

    private void Search()
    {
        if (!string.IsNullOrWhiteSpace(searchInput))
        {
            Navigation.NavigateTo($"/track/{Uri.EscapeDataString(searchInput.Trim())}");
        }
    }

    private void HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") Search();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.PickedUp => "bg-secondary",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Pending => "bg-warning text-dark",
        _ => "bg-secondary"
    };
}

@page "/shipments"
@attribute [Authorize]

@inject IShipmentService ShipmentService

<PageTitle>Shipments - Dispatcher</PageTitle>

<h2>Shipments</h2>

@if (loading)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <div class="mb-3" style="max-width: 400px;">
        <input type="text" class="form-control" placeholder="Filter by tracking # or destination..."
               @bind="filterText" @bind:event="oninput" />
    </div>

    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Shipped Date</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td>@s.TrackingNumber</td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td>
                            <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                    @bind="s.Status">
                                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@status">@status</option>
                                }
                            </select>
                        </td>
                        <td>@s.ShippedDate.ToString("MMM dd, yyyy")</td>
                        <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>
                            <button class="btn btn-sm btn-primary" @onclick="() => SaveStatus(s)">Save</button>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    @if (!FilteredShipments.Any())
    {
        <p class="text-muted">No shipments match your filter.</p>
    }
}

@if (!string.IsNullOrEmpty(message))
{
    <div class="alert alert-success mt-2" role="alert">@message</div>
}

@code {
    private List<ShipmentDto> shipments = [];
    private bool loading = true;
    private string? filterText;
    private string? message;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        string.IsNullOrWhiteSpace(filterText)
            ? shipments
            : shipments.Where(s =>
                s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
                s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase));

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
        loading = false;
    }

    private async Task SaveStatus(ShipmentDto shipment)
    {
        await ShipmentService.UpdateStatusAsync(shipment.Id, shipment.Status);
        message = $"Status updated for {shipment.TrackingNumber}.";
        await Task.Delay(2000);
        message = null;
    }
}

