5. 
6. public class ShipmentHttpService(HttpClient http) : IShipmentService
7. {
8.     public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
9.     {
10.         return await http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments") ?? [];
11.     }
12. 
13.     public async Task<ShipmentDto?> GetByTrackingNumberAsync(string trackingNumber)
14.     {
15.         var response = await http.GetAsync($"/api/shipments/track/{Uri.EscapeDataString(trackingNumber)}");
16.         if (!response.IsSuccessStatusCode)
17.             return null;
18.         return await response.Content.ReadFromJsonAsync<ShipmentDto>();
19.     }
20. 
21.     public async Task<ShipmentDto?> GetByIdAsync(int id)
22.     {
23.         var response = await http.GetAsync($"/api/shipments/{id}");
24.         if (!response.IsSuccessStatusCode)
25.             return null;
26.         return await response.Content.ReadFromJsonAsync<ShipmentDto>();
27.     }
28. 
29.     public async Task UpdateStatusAsync(int id, ShipmentStatus newStatus)
30.     {
31.         await http.PutAsJsonAsync($"/api/shipments/{id}/status", newStatus);
32.     }
33. }
