 @page "/shipments"
 @attribute [Authorize]

 @inject IShipmentService ShipmentService

 <PageTitle>Shipments - Dispatcher</PageTitle>

 <h2>Shipments</h2>

 @if (loading)
 {
     <p><em>Loading shipments...</em></p>
 }
 else
 {
     <div class="mb-3" style="max-width: 400px;">
         <input type="text" class="form-control" placeholder="Filter by tracking # or destination..."
                @bind="filterText" @bind:event="oninput" />
     </div>

     <div class="table-responsive">
         <table class="table table-striped table-hover">
             <thead>
                 <tr>
                     <th>Tracking #</th>
                     <th>Origin</th>
                     <th>Destination</th>
                     <th>Status</th>
                     <th>Shipped Date</th>
                     <th>Est. Delivery</th>
                     <th>Actions</th>
                 </tr>
             </thead>
             <tbody>
                 @foreach (var s in FilteredShipments)
                 {
                     <tr>
                         <td>@s.TrackingNumber</td>
                         <td>@s.Origin</td>
                         <td>@s.Destination</td>
                         <td>
                             <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                     @bind="s.Status">
                                 @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                 {
                                     <option value="@status">@status</option>
                                 }
                             </select>
                         </td>
                         <td>@s.ShippedDate.ToString("MMM dd, yyyy")</td>
                         <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                         <td>
                             <button class="btn btn-sm btn-primary" @onclick="() => SaveStatus(s)">Save</button>
                         </td>
                     </tr>
                 }
             </tbody>
         </table>
     </div>

     @if (!FilteredShipments.Any())
     {
         <p class="text-muted">No shipments match your filter.</p>
     }
 }

 @if (!string.IsNullOrEmpty(message))
 {
     <div class="alert alert-success mt-2" role="alert">@message</div>
 }

 @code {
     private List<ShipmentDto> shipments = [];
     private bool loading = true;
     private string? filterText;
     private string? message;

     private IEnumerable<ShipmentDto> FilteredShipments =>
         string.IsNullOrWhiteSpace(filterText)
             ? shipments
             : shipments.Where(s =>
                 s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
                 s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase));

     protected override async Task OnInitializedAsync()
     {
         shipments = await ShipmentService.GetAllShipmentsAsync();
         loading = false;
     }

     private async Task SaveStatus(ShipmentDto shipment)
     {
         await ShipmentService.UpdateStatusAsync(shipment.Id, shipment.Status);
         message = $"Status updated for {shipment.TrackingNumber}.";
         await Task.Delay(2000);
         message = null;
     }
 }

