     <div class="d-flex gap-2" style="max-width: 500px;">
         <input type="text" class="form-control" placeholder="e.g. TRK-2026-001"
                @bind="searchInput" @bind:event="oninput"
                @onkeydown="HandleKeyDown" />
         <button class="btn btn-primary" disabled="@string.IsNullOrWhiteSpace(searchInput)"
                 @onclick="Search">Search</button>
     </div>
 }
 else if (loading)
 {
     <p><em>Loading shipment details...</em></p>
 }
 else if (shipment is null)
 {
     <div class="alert alert-warning">Shipment not found for tracking number: <strong>@TrackingNumber</strong></div>
     <button class="btn btn-secondary" @onclick="@(() => Navigation.NavigateTo("/track"))">Try Another</button>
 }
 else
 {
     <div class="card" style="max-width: 600px;">
